/* SPDX-License-Identifier: MPL-2.0 */

'use strict';

/**
 * Which RGAA tests each rule checks, per RGAA version.
 *
 * PURPOSE
 * -------
 * RGAA does not restate WCAG criterion by criterion (WCAG 1.1.1 alone relates
 * to 19 RGAA criteria), so a rule's RGAA tests cannot be derived from its WCAG
 * mapping the way an EN 301 549 clause is. They are stated here, rule by rule.
 *
 * THE MAPPING RULE
 * ----------------
 * A rule maps to a test when a failure of the rule (or, for a manual rule, the
 * question it raises) is direct evidence about what the test's official
 * methodology checks, on the same kind of element. Covering one step of a
 * multi-step test is enough; sharing a WCAG criterion, or a theme, is not.
 * A rule that checks presence maps to the presence test, a manual "quality"
 * rule to the relevance test. `note` says which step and why, for review.
 *
 * A rule that fails is linked to a test only when its usual failures really
 * fail that test. Where that is uncertain, the test is left off (when the
 * problem is already reported under a test it certainly fails) or the rule
 * asks (cantTell) instead of failing. A question is never a false failure, so
 * a manual rule may link to any test its question bears on.
 *
 * The build rejects an unknown rule id or test id, a field other than tests,
 * note and outsideCorrespondence, and a rule mapped to WCAG criteria none of
 * which RGAA relates to the test's criterion, unless outsideCorrespondence
 * says why (src/coverage/rgaa-mappings.js). A rule with no WCAG mapping may
 * map to any test: RGAA checks some things WCAG leaves to best practice, such
 * as heading hierarchy and landmarks.
 *
 * REVIEW STATUS: drafted from the RGAA 4.1.2 test wording and methodology
 * (scripts/data/rgaa/), then checked row by row against how other RGAA tools
 * map and flag the same checks. Not yet reviewed by an RGAA auditor.
 */

const RGAA_RULE_TESTS = {
  '4.1.2': {
    "accesskeys": { tests: [], note: "Asks for review of duplicate accesskey values across elements. 12.10.1 concerns single-key shortcuts without modifiers, and accesskey always uses a modifier. The Nu checker (8.2.1) does not treat the same accesskey on different elements as an error. No RGAA test checks this." },
    "area-alt-present": { tests: ["1.1.2"], note: "Fails an <area href> in a used image map that has no non-empty alt/aria-label/aria-labelledby/title, which is the presence check of 1.1.2 step 3 (a linked area is always informative). Partial: the rule also accepts title and aria-labelledby, which 1.1.2 does not list, so a pass is weaker evidence than a fail; area-alt-source fails an area named only that way." },
    "area-alt-quality": { tests: ["1.3.2"], note: "Asks a human to judge the text alternative of a linked <area> named by a non-empty alt, aria-label, aria-labelledby or title, listing each source present, which is exactly 1.3.2 step 2 (relevance of the area's text alternative)." },
    "area-alt-source": { tests: ["1.1.2"], note: "Fails a linked <area> of a used image map whose only non-empty name sources are title or aria-labelledby: 1.1.2 step 3 lists only aria-label and alt. A linked area always carries information. An area with no source at all is left to area-alt-present. The glossary's clause on the value assistive technologies really render leaves some room for aria-labelledby, which the rule does not take." },
    "aria-allowed-attr": { tests: [], note: "Fails when an aria-* attribute is neither global nor supported by the element's role (WCAG 4.1.2). Not linked to 8.2.1, where the W3C validator decides: the rule fails <h2 aria-expanded>, which the validator accepts, skips elements whose role depends on context (a[href], td, section, summary), where the validator reports errors, and skips hidden content, which 8.2.1 judges. aria-attribute-conformance reports 8.2.1. Not mapped to 7.1.1 (where other RGAA tools put this check): the rule also fires on static markup, which is not a scripted component." },
    "aria-allowed-role": { tests: [], note: "Asks about explicit roles that ARIA in HTML does not permit on the host element (for example role=tab on nav); it never fails. Not linked to 8.2.1: the W3C validator reports these as errors, so a question is too weak there, and the rule misses main and table cells. aria-role-conformance reports 8.2.1. Whether the role is appropriate for the component (7.1.3) is a separate judgment that the rule does not make." },
    "aria-attribute-conformance": { tests: ["8.2.1"], note: "Fails, hidden content included, what the W3C validator (version 26.9.27) reports about aria-* attributes: an unknown name, an invalid value (empty, misspelt or out of range, an aria-activedescendant pointing to nothing), an attribute the role or element does not support (aria-pressed on a link, aria-sort on a native td, aria-expanded on a details summary), a name on an element that cannot be named (aria-label on a div, span, p or caption), aria-checked on a native checkbox or radio, a state that contradicts a native attribute, and a missing required attribute even where ARIA gives a default (role=heading without aria-level). That is 8.2.1 step 2, attributes and values following the writing rules. It passes what the validator accepts: aria-expanded on a heading, an aria-describedby that points to nothing." },
    "aria-braille-equivalent": { tests: [], note: "Fails when aria-braillelabel is used without a regular accessible name, or aria-brailleroledescription without aria-roledescription, on any element. No RGAA test targets these ARIA 1.3 attributes. The missing-name case would only be evidence for 7.1.1 (explicit name) on a scripted component, which the rule does not identify. Reviewer may consider 8.2.1 if the validator flags it." },
    "aria-checked-state-mismatch": { tests: [], note: "Asks about native checkbox/radio inputs whose explicit aria-checked disagrees with their real state (WCAG 4.1.2). Not linked to 8.2.1: the W3C validator reports any aria-checked on these inputs, whatever its value, and the rule says nothing when the value agrees. aria-attribute-conformance reports 8.2.1. Not mapped to 7.1.1 (where other RGAA tools put this check): a native input is not a scripted component." },
    "aria-conditional-attr": { tests: [], note: "Flags aria-errormessage without a non-false aria-invalid (reported as cantTell). A field can legitimately carry an inert aria-errormessage while no error is shown. 11.10.3/11.10.6 accept a visible message naming the field instead of aria-invalid, so this is not direct evidence for any RGAA test." },
    "aria-deprecated-role": { tests: [], note: "Flags roles that WAI-ARIA deprecates or reserves for user agents (e.g. generic). The spec only advises against these ('SHOULD NOT'); it does not make them invalid, so this is not a failed 8.2.1 validity condition. No other RGAA test covers the choice of role outside scripted components (7.1.3)." },
    "aria-hidden-body": { tests: ["10.8.1"], note: "Fails aria-hidden=\"true\" on <body>, which hides the whole page from AT. 10.8.1 step 1 lists aria-hidden elements as hidden content, and step 2 requires hidden content to be meant to be ignored, which the whole page never is." },
    "aria-hidden-focus": { tests: ["10.8.1"], note: "Fails when an aria-hidden=true element is focusable or contains focusable descendants. That is direct evidence for 10.8.1 step 2 on aria-hidden content: keyboard users can reach content hidden from assistive technology, so it is not content meant to be ignored, yet it is not made available to AT. Other candidates (images, frames, scripts) are not about this element-level condition." },
    "aria-list-item-roles": { tests: ["9.3.1","9.3.2"], note: "Asks about an element with role=\"list\" (not <ul> or <ol>) whose children do not all have role=\"listitem\", <li> elements without that role included: 9.3.1 and 9.3.2 step 2 accept only <ul>/<ol> with <li>, or role=\"list\" with role=\"listitem\". It asks rather than fails, because whether the content is visually a list, and an ordered or unordered one, only a person can tell." },
    "aria-prohibited-attr": { tests: [], note: "Fails when aria-label/aria-labelledby is set on roles where ARIA prohibits naming (generic, paragraph, strong...), and asks when the element has text (WCAG 4.1.2). Not linked to 8.2.1: the W3C validator reports every such attribute as an error, including the cases this rule asks about and the ones it exempts inside a widget, and on a native <caption>. aria-attribute-conformance reports 8.2.1. Not mapped to 7.1.1 (where other RGAA tools put this check): the rule fires on plain div, span and p elements, which are not scripted components." },
    "aria-prohibited-children": { tests: [], note: "Fails a container role that owns a child with a disallowed role. Not mapped to 9.3.1/9.3.2: most findings are on widget containers (listbox, menu, tablist, tree, radiogroup), which the 9.3 technical note says are not equivalent to an HTML list. For role=\"list\", aria-list-item-roles asks about items without role=\"listitem\". Not mapped to 7.1.1: the widget-role link is indirect." },
    "aria-required-attr": { tests: [], note: "Fails when an explicit role lacks a required state/property (e.g. role=checkbox without aria-checked), and asks where WAI-ARIA gives a default value (WCAG 4.1.2). Not linked to 8.2.1: the W3C validator reports those defaulted cases as errors too (role=heading without aria-level). aria-attribute-conformance reports 8.2.1. Not mapped to 7.1.1 (where other RGAA tools put this check): its methodology steps (role, name, name consistent with state) do not check state attributes, and the rule also fires on elements no script drives." },
    "aria-required-children": { tests: [], note: "Asks (cantTell) whether a container role owns none of its required child roles. Not mapped to 9.3.1/9.3.2: most findings are on widget containers (tablist, menu, listbox, tree), which the 9.3 technical note says are not equivalent to an HTML list. For role=\"list\", aria-list-item-roles asks about items without role=\"listitem\". Not mapped to 7.1.1: the widget-role link is indirect." },
    "aria-required-parent": { tests: [], note: "Fails roles such as listitem, option, tab, menuitem, treeitem or row with no valid context parent. Not mapped to 9.3.1/9.3.2: most findings are on widget items (option, tab, menuitem, treeitem), and the 9.3 technical note says those widgets are not equivalent to an HTML list. An orphan role=\"listitem\" is left to the list rules (listitem-parent-valid, fake-list). The table roles (row/cell) are not mapped, because 5.6 only checks header declaration. Not mapped to 7.1.1: the widget-role link is indirect." },
    "aria-role-conformance": { tests: ["8.2.1"], note: "Fails, hidden content included, what the W3C validator (version 26.9.27) reports about role attributes: an empty value, a token that is not a role it accepts (misspelt, abstract, written with capitals, alone or in a list), a role not allowed on the element (tab on nav, navigation on main, any role on a native td), and an img with a role and an empty or missing alt. That is 8.2.1 step 2, attribute values following the writing rules. An img with role=\"presentation\" and an empty or missing alt is asked about: the validator reports it, but RGAA 1.2.1 names that markup for decorative images." },
    "aria-role-name-present": { tests: ["7.1.1","11.6.1"], note: "Fails when role grid, meter, progressbar, radiogroup or tree has no aria-label, aria-labelledby or title, and no name from its host element (the legend of a fieldset, the caption of a table, the label of a <progress> or <meter>). For radiogroup, this is 11.6.1 step 2 (group has aria-label or aria-labelledby); for grid and tree widgets, 7.1.1 step 2 (component has an explicit name), which no other test covers. 11.6.1 can still pass through per-field labels (step 3). Not mapped to 11.1.1: an unnamed meter or progressbar is a form field without a label, which field-label-listed-source reports under 11.1.1 for every field, so a link here would count the same field twice.", outsideCorrespondence: {"11.6.1":"For role=\"radiogroup\" only: 11.6.1 step 2 requires a radiogroup to have aria-label or aria-labelledby. RGAA relates 11.6 to WCAG 1.3.1 and 3.3.2, while the engine files naming under 4.1.2."} },
    "aria-roles-valid": { tests: [], note: "Fails when no token of an explicit role is a real, non-abstract WAI-ARIA role, and asks on a native element whose role is unknown (WCAG 4.1.2). Not linked to 8.2.1: the W3C validator reports every unknown token, one in a list (role=\"bogus button\") or written with capitals (role=\"BUTTON\"), which this rule passes. aria-role-conformance reports 8.2.1. Not mapped to 7.1.1 (where other RGAA tools put this check): the rule also fires on static markup, which is not a scripted component." },
    "aria-text": { tests: [], note: "Checks that role=\"text\" containers have no focusable descendants. role=\"text\" is a non-standard ARIA value and no RGAA test examines it or the focusability of its content; 7.1.1 concerns roles of scripted components, not this pattern." },
    "aria-valid-attr": { tests: [], note: "Asks about aria-* attribute names not defined by WAI-ARIA (WCAG 4.1.2). Not linked to 8.2.1: the W3C validator reports these as errors, so a question is too weak there, and the rule skips hidden content. aria-attribute-conformance reports 8.2.1. Not mapped to 7.1.1 (where other RGAA tools put this check): the rule also fires on static markup, which is not a scripted component." },
    "aria-valid-attr-value": { tests: [], note: "Flags recognized aria-* attributes whose value does not match the declared type (WCAG 4.1.2), and asks about an idref list that resolves to nothing. Not linked to 8.2.1: it passes values the W3C validator rejects (aria-expanded=\"\", a token with surrounding spaces) and skips hidden content. aria-attribute-conformance reports 8.2.1. Not mapped to 7.1.1 (where other RGAA tools put this check): the rule also fires on static markup, which is not a scripted component." },
    "autocomplete-valid": { tests: ["11.13.1"], note: "Fails a non-empty autocomplete value that is not on/off or a well-formed autofill token list, or whose field name does not suit the control type (street-address on a single-line input, email on a number input). That covers the 11.13.1 step-2 condition that the value is in the list of allowed values; it does not check that the attribute is present or relevant. Not linked to 8.2.1: the rule exempts disabled fields and fixed-value input types, which the W3C validator still checks; html-elements-attributes-valid reports invalid autocomplete values under 8.2.1." },
    "avoid-inline-spacing": { tests: ["10.12.1"], note: "Fails text whose inline style forces line-height, letter-spacing or word-spacing with !important below the WCAG 1.4.12 values. That setting defeats the style override in 10.12.1 step 1, so the text cannot receive the required spacing. Text that may never wrap (a single word, text not allowed to wrap, or text short enough to fit on one line at 320 CSS pixels) is asked about instead of failed. The rule does not check the readability or loss of content of step 2." },
    "binary-control-name-present": { tests: [], note: "Checks that elements with explicit role checkbox, radio or switch have a name from aria-labelledby, aria-label, title, an associated label or their content. It accepts a wrapping <label> and a name from content, which 11.1.1 does not list, so a pass is not an 11.1.1 pass. Not mapped to 11.1.1: field-label-listed-source reports 11.1.1 for every form field, from the sources 11.1.1 lists only. Not mapped to 7.1.1: it passes when an accessible alternative exists." },
    "button-name-present": { tests: [], note: "Flags button, input button/submit/reset and role=button with an empty accessible name. Not mapped to 11.9.1: that test covers only the buttons inside a form (a <form> or role=\"form\"), and most unnamed buttons are outside one; form-button-name-present reports the buttons in a form there. Not mapped to 7.1.1 either: it passes when an accessible alternative exists, so a failure under it is not certain." },
    "bypass-blocks-present": { tests: ["12.6.1"], note: "Raises a review question only when the page has no exposed <main>/role=main, no working same-page anchor link and no visible heading, i.e. the main content zone has none of the 12.6.1 step-2 mechanisms (landmark, heading, skip/quick-access link). Not mapped to 12.7.1: a main landmark or a heading silences the rule, but 12.7.1 accepts only a link to the main content zone, which skip-link-present checks." },
    "canvas-decorative-aria-hidden": { tests: ["1.2.5"], note: "Checks each <canvas> marked decorative, without a caption. Fails aria-hidden=\"true\" with aria-labelledby, aria-label, title, a child alternative or text inside the canvas (1.2.5 conditions 2 and 3; if the canvas carries information, hiding it fails 1.1.8 instead), and role=\"none\"/\"presentation\" without aria-hidden=\"true\" and with no content (condition 1). Asks when such a canvas has fallback content, which makes it an informative canvas that passes 1.1.8 if the content is its alternative." },
    "canvas-role-img": { tests: ["1.1.8"], note: "Checks each <canvas> not marked decorative. Passes role=\"img\" with aria-labelledby or aria-label (steps 3 and 4), or, without role=\"img\", fallback content (step 6). Fails a <canvas role=\"img\"> with no ARIA name, since the note of the methodology limits its alternative to step 4, and a canvas with no role, no fallback content and no link or button after it, even if aria-label or title names it. Asks when a link or button follows the canvas. A replacement mechanism cannot be detected." },
    "canvas-text-alternative-present": { tests: [], note: "Fails a <canvas> with neither fallback content nor an accessible name, and a <canvas role=\"img\"> with no aria-label, aria-labelledby or title. Not mapped to 1.1.8: RGAA passes a canvas followed by a link or button to an alternative content, which this rule fails, and it accepts an aria-label or title without role=\"img\", which 1.1.8 does not. canvas-role-img checks 1.1.8 as RGAA words it, and canvas-decorative-aria-hidden checks 1.2.5 for a canvas marked decorative." },
    "canvas-text-alternative-quality": { tests: ["1.3.7","1.3.8"], note: "Asks a human to judge a canvas's existing name or fallback content. That is 1.3.7 step 2 (the alternative is relevant) and, for fallback content between <canvas> and </canvas>, 1.3.8 step 2 (that content is correctly rendered by assistive technologies), which only a test with them can tell." },
    "combobox-name-present": { tests: [], note: "Checks that role=combobox has a name from aria-label, aria-labelledby, title or an associated label. It accepts a wrapping <label> and a placeholder on a text-like <input>, which 11.1.1 does not list, so a placeholder-only field passes here while it fails 11.1.1. Not mapped to 11.1.1: field-label-listed-source reports 11.1.1 for every form field, from the sources 11.1.1 lists only. Not mapped to 7.1.1: it passes when an accessible alternative exists." },
    "complex-table-summary": { tests: ["5.1.1"], note: "Asks whether a summary is available for a <table> or role=\"table\" the rule takes as complex: a header cell outside both the first row and the first column, a cell with a headers attribute, a header with scope=\"rowgroup\" or \"colgroup\", or first-row (or first-column) headers that each span a group of columns (or rows), as in RGAA's definition of a complex data table. A table with aria-describedby is not asked about, nor one with a summary attribute in a document whose doctype is not HTML5 (5.1.1 step 2 accepts summary only before HTML5). The summary may sit in the caption or next to the table, which only a person can judge." },
    "complex-table-summary-quality": { tests: ["5.2.1"], note: "Asks whether the summary of a complex data table is relevant, which is 5.2.1 step 2. Complex tables are found as complex-table-summary finds them for 5.1.1. The summary is a <caption> with text, an aria-describedby that points to text, or, before HTML5 only, a summary attribute (5.1.1 step 2). A table with no summary is 5.1.1's matter." },
    "contrast-computable": { tests: ["3.2.1","3.2.2","3.2.3","3.2.4"], note: "Returns cantTell for visible text whose contrast cannot be computed (background image or gradient, blend mode, filter, text-shadow, opacity). This marks the text that 3.2.1 to 3.2.4 step 1 must find and measure by hand; it never gives a verdict. It does not check the paired CSS color declarations of 10.5, so 10.5 is not mapped." },
    "contrast-enhanced": { tests: [], note: "AAA check (7:1 / 4.5:1). RGAA has no enhanced-contrast test, and failing 7:1 says nothing about the 4.5:1 / 3:1 thresholds of 3.2.x (contrast-minimum covers those)." },
    "contrast-minimum": { tests: [], note: "Fails computable text below 4.5:1 (normal) or 3:1 (large) under WCAG 1.4.3, where bold text is large from 14pt (about 18.67px). Not linked to 3.2.1 to 3.2.4: RGAA makes bold text large from 18.5px, so this rule fails bold text from 18.5 to 18.67px with a ratio between 3:1 and 4.5:1, which 3.2.4 passes. contrast-minimum-rgaa reports 3.2.1 to 3.2.4 with RGAA's threshold." },
    "contrast-minimum-rgaa": { tests: ["3.2.1","3.2.2","3.2.3","3.2.4"], note: "Fails computable text below 4.5:1, or below 3:1 for text of 24px or more and bold text of 18.5px or more, which is step 2 of 3.2.1 to 3.2.4 with RGAA's own sizes. Same code as contrast-minimum apart from the bold threshold. Caveats: it does not look for a mechanism that shows the text with enough contrast (the second condition of each test), nor for logos or decorative text (particular cases)." },
    "css-focus-indicator-suppressed": { tests: ["10.7.1"], note: "Flags tab-order elements whose outline is removed, by a :focus/:focus-visible rule or by a rule with no state such as a { outline: none }, with no border, box-shadow or background replacement in any matching focus rule. That is 10.7.1 condition 1 (native focus style removed) and step 2 (visual focus indicator present). The 3:1 contrast part of step 2 is focus-indicator-contrast's." },
    "css-hidden-focus": { tests: ["10.7.1"], note: "Flags keyboard-focusable elements that are visually hidden (opacity 0, clipped, off-screen, zero-size with overflow hidden), so taking focus on them gives no visible indication. An element that a :focus/:focus-visible rule brings back into view, such as an off-screen skip link, is not flagged. This is evidence for 10.7.1 step 2 on focusable elements. It is not 10.8.1, because the content stays exposed to AT and the problem is purely visual." },
    "css-orientation-lock": { tests: ["13.9.1"], note: "Fails an @media (orientation) block that rotates the page by about 90 degrees, a known way to force one orientation. That is direct evidence that viewing is not possible in both portrait and landscape (13.9.1 step 2). An orientation block that hides the main content (a \"rotate your device\" message) is asked about. The essential-orientation exception still needs a human." },
    "data-table-headers-review": { tests: ["5.6.1","5.6.2"], note: "Asks about a table of at least two rows and two columns that has no header cell at all (no <th>, no columnheader or rowheader role), and is not role=\"presentation\" or \"none\". If it is a data table, its headers over a whole column or row fail 5.6.1 or 5.6.2 unless marked with <th> or those roles; only a person can say whether it is a data table and which cells are headers. A table with at least one header is not asked about." },
    "definition-list-children-valid": { tests: ["9.3.3"], note: "Fails a <dl> whose children are not dt/dd groups (one wrapping div allowed), that has text directly inside it, or whose dt/dd set is unbalanced or out of order (a dd before the first dt, a dt after the last dd), so the description list is not correctly built from <dl>/<dt>/<dd>, which is step 2 of 9.3.3. Not linked to 8.2.1: the rule accepts some content the HTML content model rejects (such as a <style> child) and skips hidden lists; html-nesting-valid reports the dl content model under 8.2.1." },
    "deprecated-elements-not-used": { tests: [], note: "Asks about each <marquee>, the only element it reports (<blink> is left out, since no browser makes it blink). Not mapped to 10.1.1, where presentational-elements-absent already reports <marquee> and <blink>: linking both would count the same element twice. Not mapped to 8.2.1: html-elements-attributes-valid fails every obsolete element there, hidden ones included, and a question on the same <marquee> would count it twice. Not mapped to 13.8.1/13.8.2: even a <marquee> that can be paused passes 13.8.1, so moving content is left to the auditor." },
    "dialog-name-present": { tests: ["7.1.1"], note: "Checks that role=dialog/alertdialog (the first concrete token of the role attribute) and an open native <dialog> have a name from aria-label, aria-labelledby or title. A dialog is a script-driven interface component, and 7.1.1 step 2 requires it to have an explicit name. No other RGAA test covers dialog naming. Medium because 7.1.1 can still pass through an accessible alternative." },
    "dir-attribute-valid": { tests: ["8.10.2"], note: "Fails a dir attribute whose value is not rtl or ltr, which is the first condition of 8.10.2 (\"La valeur de l’attribut dir est conforme (rtl ou ltr)\"). dir=\"auto\", valid HTML, fails too on text that reads in the reverse direction of its context, since RGAA names only the two values; on other text it is not applicable, as 8.10.2 step 1 covers only the passages of 8.10.1. A value with surrounding spaces fails: browsers ignore it. Whether the direction is right for the text (the second condition) needs a human." },
    "dlitem-parent-valid": { tests: ["9.3.3"], note: "Fails a <dt>/<dd> that is not inside a <dl> (directly or via one div), so a description list is not structured with <dl>, <dt> and <dd> (9.3.3 step 2). Not linked to 8.2.1: html-nesting-valid reports an orphan dt or dd there, hidden content included, so a link here would count it twice." },
    "doctype-present": { tests: ["8.1.1"], note: "Fails a page with no doctype (8.1.1). A doctype written after <html> is dropped by the HTML parser, so it fails as missing; the 8.1.1 methodology checks the doctype's place before <html>. Not linked to 8.1.2: doctype-valid judges the validity of a declared doctype. Not linked to 8.1.3: a late doctype cannot be told from a missing one in the DOM." },
    "doctype-valid": { tests: ["8.1.2"], note: "Fails a declared doctype that is neither the HTML5 doctype nor one the W3C recommends (HTML 2.0 to 4.01, XHTML 1.0 and 1.1, XHTML Basic, XHTML plus MathML/SVG, the RDFa doctypes), which is 8.1.2. A page with no doctype is not applicable here; doctype-present fails it under 8.1.1." },
    "duplicate-id": { tests: ["8.2.1"], note: "Fails on non-empty id values that are not unique in their document or shadow tree, compared as written (id=\"a \" and id=\"a\" differ). That is the 8.2.1 condition 'Les valeurs d'attribut id sont uniques dans la page'." },
    "duplicate-id-aria": { tests: [], note: "Flags duplicate id values that ARIA ID-reference attributes point to (WCAG 4.1.2). Not linked to 8.2.1: duplicate-id already fails every duplicate id under 8.2.1, these included, so linking this rule too would count the same ids twice." },
    "embed-image-role-img": { tests: ["1.1.7"], note: "Checks each <embed type=\"image/...\"> not marked decorative. Passes role=\"img\" with aria-labelledby, aria-label or title. Fails an embed with no text alternative and no link or button right after it, which meets none of the conditions of 1.1.7 short of a replacement mechanism the page would have to offer. Asks when there is a text alternative without role=\"img\" (the test wording requires both, the methodology validates on the alternative alone) and when a link or button follows (does it lead to an alternative content?)." },
    "embed-text-alternative-present": { tests: [], note: "Fails an <embed> with no aria-label, aria-labelledby or title. Not mapped to 1.1.7: that test covers only type=\"image/...\", while the rule fails every <embed>, and RGAA passes an embed followed by a link or button to an alternative content, which this rule fails. embed-image-role-img checks 1.1.7 as RGAA words it." },
    "embed-text-alternative-quality": { tests: ["1.3.5"], note: "Asks a human to judge the relevance of an <embed>'s existing name, which is 1.3.5 step 2. Scope mismatch: 1.3.5 only covers image embeds (type=\"image/...\"), and the rule reviews all embeds." },
    "embedded-refresh-review": { tests: ["13.1.1"], note: "Asks about every <object>, <embed> and <canvas>, and every <svg> that holds a <script>: 13.1.1 step 1 lists them as refresh methods along with <meta>. An <object> or <embed> that shows a still image is left out, and so is an <svg> with no script, which cannot reload anything. Whether the element refreshes, and whether the user can control it (step 2), needs a person." },
    "empty-heading": { tests: [], note: "Asks about <h1>-<h6>/role=\"heading\" elements with an empty accessible name. Not mapped to 9.1.2: RGAA fails an empty heading outright, which heading-content-present reports, and this rule accepts a title or aria-label name that 9.1.2 does not count as content." },
    "empty-table-header": { tests: [], note: "Flags th/columnheader/rowheader cells with no visible text. RGAA 5.6 checks that headers are declared with th or a header role, and 5.7 checks how cells are associated with them. No RGAA test covers the content or relevance of a header cell." },
    "fake-list": { tests: ["9.3.1","9.3.2"], note: "Asks whether lines or consecutive paragraphs that start with the same bullet (9.3.1) or with consecutive numbers (9.3.2) are a list, which those tests want marked up with <ul>/<ol> and <li>, or role=\"list\" and role=\"listitem\". Lists drawn with images or CSS alone are not found." },
    "field-group-legend": { tests: ["11.6.1"], note: "Asks about a <fieldset> holding form fields with no <legend>, or a role=\"group\" or role=\"radiogroup\" holding form fields with no aria-label or aria-labelledby: the only legends 11.6.1 step 2 accepts (aria-label on a plain fieldset and title on a group do not count). 11.6.1 requires a legend on each grouping of fields of the same kind; whether this group is one, and whether each field instead names the group (step 3), is left to a person." },
    "field-label-in-name-sources": { tests: ["11.2.5"], note: "Fails a form field (glossary \"Champ de saisie de formulaire\", native and ARIA) with a visible label when its aria-label, the text its aria-labelledby points to, its title or the content of its <label> does not contain that label. That is 11.2.5 as written: each source, when present, contains at least the visible label, not only the one that gives the accessible name. Punctuation and capital letters are ignored (particular cases of 11.2). Asks when the visible label may be a symbol, or when a source differs only by an abbreviation or by text in parentheses. The visible label is read from the <label>, else from aria-labelledby, else from the field's own text for the checkbox, radio and switch roles." },
    "field-label-listed-source": { tests: ["11.1.1"], note: "Fails a form field (those of the glossary entry \"Champ de saisie de formulaire\", native and ARIA, without option, optgroup and datalist) that has none of the sources 11.1.1 lists: an aria-labelledby pointing to text, an aria-label, a <label for> or a title. A placeholder, the field's own content and an <output>'s value do not count. Asks instead when the only label is a <label> wrapping the field without for (the glossary \"Étiquette de champ de formulaire\" accepts any <label>, while 11.1.1 names a <label> with for), when a <label for> points at an element a label cannot name, and when the only source present is empty. It takes over 11.1.1 from the WCAG field-name rules, which accept a wrapping label, a placeholder or a name from content." },
    "figure-caption-structure": { tests: ["1.9.1"], note: "For a <figure> holding an image and a <figcaption> with text, fails when the figure has no role=\"figure\" or role=\"group\", or no aria-label identical to the caption: conditions 2 and 3 of 1.9.1. Conditions 1 and 4 (figure and figcaption) are what make the rule apply, so a caption given another way is not found." },
    "focus-indicator-contrast": { tests: ["10.7.1"], note: "Fails an element in the tab order whose native outline a focus rule replaces or removes, when every outline, border and box-shadow of its focus style is below 3:1 against both the background behind it and the element's own background, and nothing else changes on focus. That is the contrast part of 10.7.1 step 2 (« suffisamment contrastée (ratio de contraste égal ou supérieur à 3.0) »). It asks when a color, a background or the cascade cannot be worked out, when the indicator reaches 3:1 on one side only, or when the focus style is something else (background, text color, another element). An element that keeps the browser's outline meets condition 1 and is not checked." },
    "focus-order-semantics": { tests: [], note: "Flags elements with tabindex>=0 and a non-interactive explicit role (heading, list, region...). When such an element is a scripted control, 7.1.1 step 2 (role consistent with its use) directly applies. Legitimately focusable elements such as scrollable regions make this only partial evidence. Not mapped to 7.1.1: only evidence when the element is a scripted component. Not mapped to 12.8.1 (where other RGAA tools put this check): 12.8.1 checks that the tab order is coherent, not the role of what receives focus." },
    "form-button-label-in-name-sources": { tests: ["11.9.2"], note: "Fails a button inside a <form> or role=\"form\" whose accessible name does not contain its visible label (its text, or the value of an <input> button), which is 11.9.2 methodology step 2. Asks when a title, or an aria-label that loses to aria-labelledby, does not contain it: the test's conditions check every source, but its methodology checks only the accessible name. Buttons outside a form are out of scope (step 1 covers « les boutons présents au sein d'un formulaire »), and an image button shows its label inside the image. Punctuation and capital letters are ignored (particular cases of 11.2)." },
    "form-button-name-present": { tests: ["11.9.1"], note: "Fails a button (<button>, input submit/reset/button/image, role=button) inside a <form> or role=\"form\" that has no label from the sources the glossary \"Bouton (formulaire)\" lists: it has nothing whose relevance 11.9.1 step 2 could judge. Buttons outside a form are out of scope, since 11.9.1 step 1 covers only « les boutons présents au sein d'un formulaire ». Asks about a nameless button that joins a form through its form attribute from outside it, and about an image button with no alt, which the browser names with a generic \"Submit\". A pass says only that a label exists; its relevance is left to a person." },
    "form-control-label-quality": { tests: ["11.2.1","11.2.4"], note: "Takes the visible label text of a field, from a native <label> or from aria-labelledby references, and flags placeholder labels or duplicate labels with no visible context telling the fields apart. That covers 11.2.1 (the <label> content is relevant) and 11.2.4 (aria-labelledby text is relevant). aria-label and title are not used, so 11.2.2 and 11.2.3 are not covered." },
    "form-control-programmatic-label-present": { tests: [], note: "Fails input/select/textarea controls (not hidden/submit/reset/button/image) that have no associated <label>, aria-labelledby, aria-label, title or placeholder. It accepts a wrapping <label> and a placeholder, which 11.1.1 does not list, so a placeholder-only field passes here while it fails 11.1.1. Not mapped to 11.1.1: field-label-listed-source reports 11.1.1 for every form field, from the sources 11.1.1 lists only." },
    "form-control-programmatic-label-quality": { tests: ["11.1.3","11.2.2"], note: "Asks for review of native input/select/textarea controls named only by placeholder or title. A title-only label is a non-visible label: 11.1.3 step 2 asks whether that title (or adjacent visible text) makes the expected input understandable, and 11.2.2 whether the title is relevant (other RGAA tools review title-labelled fields there). Not mapped to 11.1.1: a placeholder-only field meets none of the 11.1.1 conditions, and field-label-listed-source fails it there.", outsideCorrespondence: {"11.2.2":"RGAA relates 11.2 to WCAG 1.3.1, 2.4.6, 2.5.3 and 3.3.2, while the engine files this rule under 4.1.2. A title-only field is the population of 11.2.2 step 1 (fields labelled by a title attribute), which other RGAA tools review there."} },
    "form-control-single-label": { tests: [], note: "Fails when two or more non-empty <label> elements compete for one control. No RGAA test forbids multiple labels. 11.1.1 (a label exists) and 11.1.2 (for/id match) are met in that case, and 11.2.1 judges each label's wording, not how many labels there are; multiple labels are also valid HTML, so 8.2.1 does not apply." },
    "frame-title-attribute-present": { tests: ["2.1.1"], note: "Fails an <iframe> or <frame> with no title attribute, which is 2.1.1 step 2 as written. aria-label or aria-labelledby does not replace it, and a frame with tabindex=\"-1\" is still checked. A frame with aria-hidden=\"true\" on itself or an ancestor is left out, since the glossary \"Titre de cadre\" (note 2) makes 2.1 not applicable to it. An empty title passes here: it is 2.2.1's matter." },
    "frame-title-not-empty": { tests: ["2.2.1"], note: "Fails an <iframe> or <frame> whose title attribute is empty or only spaces: 2.2.1 step 2 asks whether the title's content is relevant, and an empty one cannot be. Frames with aria-hidden=\"true\" are left out (glossary \"Titre de cadre\", note 2). Whether a non-empty title is relevant is not judged, so a pass covers only that case." },
    "heading-content-present": { tests: ["9.1.2"], note: "Fails an RGAA heading (<hx>, or role=heading with aria-level) whose content holds no text and no image with a text alternative: 9.1.2 step 1 judges the content of each heading, and an empty one has none. Asks when the only name comes from title or aria-label, or when the content is hidden text, an image with no alternative, CSS-generated text or an embedded element." },
    "heading-order": { tests: ["9.1.1"], note: "Flags heading levels that jump by more than one (hx, with its aria-level when valid, and role=heading/aria-level). This is direct input to 9.1.1 step 2, whether the heading hierarchy is relevant. RGAA does not treat every skipped level as a failure automatically, hence manual review." },
    "heading-quality": { tests: ["9.1.2"], note: "Flags headings (hx or role=heading) whose accessible name is a placeholder, template slot, filename or URL. That is 9.1.2 step 1: is each heading's content relevant." },
    "heading-role-level-present": { tests: ["9.1.3"], note: "Fails an element with role=heading and no numeric aria-level. 9.1.3 step 1 accepts only an <hx> element or role=heading with aria-level=x, and the glossary \"Titre\" defines a heading the same way; the WAI-ARIA default level of 2 does not count." },
    "html-elements-attributes-valid": { tests: ["8.2.1"], note: "Fails, hidden content included, obsolete or unknown elements and attribute values the W3C validator rejects: dir, id (empty or with whitespace), lang (not a well-formed language tag), xml:lang without a matching lang, scope, headers naming no th of the table, optgroup without label, image buttons with no alt or an empty one, and autocomplete values and placements. Each is 8.2.1's condition that tags, attributes and attribute values respect the writing rules. Asks instead on a page whose doctype is neither HTML5 nor missing, since 8.2.1 judges the source against the declared doctype. Where the validator is stricter than the HTML standard (on/off in capitals, unregistered subtags), the rule does not report." },
    "html-lang-attr-present": { tests: [], note: "Fails when lang on <html> is missing or empty, or its primary subtag is not a registered language subtag (WCAG 3.1.1). Not linked to 8.3.1 or 8.4.1: 8.3.1 also accepts xml:lang (the attribute XHTML 1.1 asks for) and a language on every text or one of its parents, such as <body lang>, which this rule fails; and the registry it checks against leaves out ISO 639-2 codes such as fra, which 8.4.1 accepts. page-language-present reports 8.3.1 and html-lang-code-valid 8.4.1." },
    "html-lang-code-valid": { tests: ["8.4.1"], note: "Fails when the language code of lang or xml:lang on <html>, the part before the first hyphen (glossary \"Code de langue\"), is not an ISO 639-1, 639-2 or later ISO 639 code: the 'valide' condition of 8.4.1 step 2. ISO 639-2 codes such as fra or ger count as valid. Not applicable without a default language on <html>. Relevance (the 'pertinent' condition) is not judged." },
    "html-nesting-valid": { tests: ["8.2.1"], note: "Fails, hidden content included, the nesting errors the W3C validator reports on lists (a ul, ol or menu child other than li, an li outside them), description lists (the dl content model, a dt or dd outside a dl), interactive content or tabindex inside a link or button, img ismap outside a link, and more than one main without the hidden attribute. That is 8.2.1's condition that tag nesting conforms. Nesting that uses only ARIA roles is a validator warning and is not reported. Asks instead on a page whose doctype is neither HTML5 nor missing, since the nesting rules of older doctypes differ." },
    "html-xml-lang-mismatch": { tests: ["8.4.1"], note: "Fails when lang and xml:lang on <html> declare different primary languages, so at least one of them does not give the document's main language (8.4.1 'pertinent'). Not mapped to 8.3.1 (where other RGAA tools put this check): the rule only applies when both attributes are present, so a language is always indicated. Not linked to 8.2.1: the validator compares the full values, so fr-FR against fr is a validity error this rule passes; html-elements-attributes-valid reports it under 8.2.1." },
    "identical-iframes-same-purpose": { tests: [], note: "Flags iframe/frame elements that share an accessible name but embed different resources (WCAG 4.1.2). Not linked to 2.2.1, which judges only the title attribute: this rule groups frames by accessible name, which may come from aria-label. iframe-title-unique asks about frames that share a title, and frame-title-not-empty fails an empty title, under 2.2.1." },
    "identical-links-same-purpose": { tests: [], note: "Asks whether links with the same name but different destinations serve the same purpose (WCAG 2.4.9 AAA, which RGAA does not cover). RGAA 6.1.x accepts context as a way to make a link explicit, so two same-named links with different targets are not direct evidence that either one fails 6.1.1 to 6.1.3." },
    "iframe-focusable-content": { tests: [], note: "Fails same-origin iframes with tabindex=-1 that contain focusable content (inconsistent keyboard reachability). No candidate fits: 7.3 is about elements with script handlers, 4.11/4.12 about media, 10.14/12.11 about extra content shown on hover or focus, and 12.9 about keyboard traps. RGAA has no general 'reachable by Tab' test for frame content." },
    "iframe-name-present": { tests: [], note: "Flags iframe/frame elements with no name from aria-labelledby, aria-label or title (WCAG 4.1.2). Not linked to 2.1.1, which asks for the title attribute on every frame: this rule passes a frame named by aria-label alone and skips frames with tabindex=\"-1\", both of which 2.1.1 fails. frame-title-attribute-present reports 2.1.1." },
    "iframe-title-unique": { tests: ["2.2.1"], note: "Asks about frames that share the same title attribute but load different resources. A shared title may not identify each frame's content, which is what 2.2.1 step 2 (title relevance) checks; only a person can tell. Frames that share a title and load the same resource pass." },
    "image-alt-long": { tests: ["1.3.9"], note: "Asks about an image (<img>, <area>, <input type=\"image\">, <svg>, <canvas>, <object>, <embed> or role=\"img\") whose text alternative (alt, aria-label, aria-labelledby, title, or an svg's <title>) is longer than 80 characters, for 1.3.9 (short and concise, particular cases aside). RGAA gives no number; 80 is a threshold for asking." },
    "image-redundant-alt": { tests: ["1.3.1"], note: "Flags <img> whose non-empty alt equals the visible text in its parent. The question is either whether the alternative is relevant (1.3.1 step 2) or whether the image is really decorative and should have alt=\"\" (1.2.1). Both tests cover the same <img> element. Not mapped to 1.2.1: a redundant alt is not evidence that a decorative image is wrongly exposed." },
    "img-alt-decorative": { tests: ["1.1.1","1.1.5","1.1.8"], note: "Asks whether an <img>, <svg> or <canvas> left out of the accessibility tree (alt=\"\", aria-hidden, role none/presentation, unlabeled svg/canvas) is really decorative. That is step 2 (does the image carry information?) of 1.1.1, 1.1.5 and 1.1.8, and a 'no' means an informative image with no alternative. It does not check the 1.2.x conditions for correctly ignoring decorative images." },
    "img-alt-present": { tests: ["1.1.1","1.2.1"], note: "Fails an exposed <img> (not hidden, not a non-focusable role none/presentation) that has no alt, no ARIA name and no title. If the image is informative, that fails 1.1.1 step 3. If it is decorative, it lacks the alt=\"\" / aria-hidden / role=presentation that 1.2.1 step 2 requires." },
    "img-alt-quality": { tests: ["1.3.1"], note: "Asks a human to judge the relevance of a non-empty <img> alt, which is 1.3.1 step 2." },
    "img-decorative-no-alternative": { tests: ["1.2.1"], note: "Checks each <img> marked decorative (alt=\"\", aria-hidden=\"true\" or role none/presentation), without a caption, for aria-labelledby, aria-label or title, which 1.2.1 step 2 forbids. Fails when the image also has aria-hidden=\"true\": it is decorative for assistive technologies, and if it carries information, hiding it fails 1.1.1 instead. Asks otherwise, since an image with alt=\"\" and a title may be informative, and then 1.1.1 accepts the title as its alternative." },
    "input-image-alt-decorative": { tests: ["1.3.3"], note: "Flags an <input type=\"image\"> whose alt is empty but which is named by aria-label, aria-labelledby or title. RGAA has no decorative image button: 1.1.3 requires every one to have a text alternative, and here one exists, so the question left is whether that name is relevant, which is 1.3.3 (\"S’il est présent, le contenu de l’attribut WAI-ARIA aria-label est pertinent\", and the same for title and aria-labelledby)." },
    "input-image-alt-present": { tests: ["1.1.3"], note: "Fails an image button with no ARIA name, no non-empty alt and no title, which is the presence check of 1.1.3 step 3. An author name equal to the browser's default (\"Submit\", \"Submit Query\") is a text alternative, so 1.1.3 is met; the rule only asks about it, since its relevance is 1.3.3's question." },
    "input-image-alt-quality": { tests: ["1.3.3"], note: "Asks a human to judge the relevance of an image button's text alternative (a non-empty alt, aria-label, aria-labelledby or title, each source listed), which is 1.3.3 step 2. An empty alt with another name is input-image-alt-decorative's question." },
    "keyboard-only-event-handlers": { tests: ["7.3.1"], note: "Asks about each element that is not interactive natively and has an inline key handler (onkeydown, onkeyup, onkeypress) but no inline click or pointer handler. 7.3.1 steps 4 and 5 require the action to work with any pointing device too, or an equivalent element that does, which WCAG 2.1.1 does not ask. It only sees inline attributes, so it never fails." },
    "label-for-target-valid": { tests: ["11.1.2"], note: "Fails a <label for> whose value is empty, matches no id in the label's tree, or matches an element that cannot be labelled and has no form-field role: then the field it names has no id equal to the for value, the condition 11.1.2 step 2 checks. A for matching an ARIA field (role=textbox and the other roles the glossary counts) meets 11.1.2; its missing name is 11.1.1." },
    "label-in-name": { tests: [], note: "Checks WCAG 2.5.3: for controls with aria-label or aria-labelledby and a visible label, the accessible name contains the visible text. Not mapped to RGAA: 6.1.5 and 11.2.5 check every name source present, the title included, not only the accessible name, and each finding belongs to one test by element type, while this rule would put all four tests on every finding. link-label-in-name-sources (6.1.5), field-label-in-name-sources (11.2.5), form-button-label-in-name-sources (11.9.2, buttons inside a form only) and widget-label-in-name (7.1.3) report them instead." },
    "label-title-only": { tests: ["11.1.3","11.2.2"], note: "Flags form fields whose only label is the title attribute, a label that is not visible. 11.1.3 covers fields whose label is not visible, and its first condition accepts a title \"dont le contenu permet de comprendre la nature de la saisie attendue\"; 11.2.2 asks whether each title \"permet de connaître la fonction exacte du champ\". The reviewer answers both from the flagged field." },
    "landmark-banner-is-top-level": { tests: [], note: "Checks that the banner landmark is not nested inside another landmark. Neither 9.2.1 (header structured with <header>) nor 12.6.1 (the zone has a matching landmark or another way to reach or skip it) checks landmark nesting." },
    "landmark-complementary-is-top-level": { tests: [], note: "Checks that complementary/<aside> is not nested inside another landmark. RGAA has no requirement about complementary landmarks or their nesting (9.2.1 and 12.6.1 do not cover aside)." },
    "landmark-contentinfo-is-top-level": { tests: [], note: "Checks that contentinfo is not nested inside another landmark. 9.2.1 only requires the footer zone to use <footer>, and 12.6.1 only requires a matching landmark or an alternative. Neither checks nesting." },
    "landmark-main-is-top-level": { tests: [], note: "Checks that main is not nested inside another landmark. 9.2.1 requires the main zone to use a single visible <main> but says nothing about where it sits; no RGAA test checks nesting." },
    "landmark-no-duplicate-banner": { tests: [], note: "Checks for more than one banner landmark. 9.2.1 requires the header zone to use <header> but does not require it to be unique (uniqueness is only required for <main>)." },
    "landmark-no-duplicate-contentinfo": { tests: [], note: "Checks for more than one contentinfo landmark. 9.2.1 requires the footer zone to use <footer> but does not require it to be unique (uniqueness is only required for <main>)." },
    "landmark-no-duplicate-main": { tests: [], note: "Flags more than one main landmark exposed to assistive technology (hidden ones are filtered out). Not linked to 9.2.1: step 5 requires every other <main> to carry the hidden attribute, so a second <main> hidden by CSS or aria-hidden alone fails it but not this rule; the rule also counts role=\"main\", and it applies whatever the doctype, while 9.2 does not apply outside HTML5. main-element-structure reports 9.2.1." },
    "landmark-one-main": { tests: [], note: "Flags pages with no main landmark. Not linked to 9.2.1: step 4 requires a <main> element, and this rule accepts role=\"main\" without one; it also applies whatever the doctype, while 9.2 does not apply outside HTML5. main-element-structure reports 9.2.1." },
    "landmark-unique": { tests: [], note: "Checks that landmarks sharing a role have distinct accessible names. No RGAA test requires landmarks to have names or unique names; 12.6.1 only requires a landmark role matching the zone's nature." },
    "layout-table-no-data-markup": { tests: ["5.8.1"], note: "Fails a table with role=\"presentation\" or role=\"none\" that has a non-empty summary, a <caption>, <th>, <thead>, <tfoot>, <colgroup>, a rowheader or columnheader role, or cells with scope, headers or axis. Those are the two conditions of 5.8.1, applied to tables marked as layout. Such a table that looks like a data table (a full header row or column over data) is asked about instead, since role=\"presentation\" on a data table is not a 5.8.1 matter. A layout table with no role is not found; deciding which tables are layout tables is 5.3." },
    "letters-spaced-with-spaces": { tests: ["10.1.3"], note: "Asks about four or more single letters in a row separated by spaces (three capitals when they are the whole text), read across inline elements, the first condition of 10.1.3 (\"Les espaces ne sont pas utilisées pour séparer les lettres d’un mot\"). Spaces used to simulate tables or columns (the other two conditions) are not looked for." },
    "link-content-label-present": { tests: ["6.2.1"], note: "Fails a[href] and role=link elements whose content has no text and no image with a text alternative, even when aria-label, aria-labelledby or title names them: 6.2.1 step 2 checks that the content of the link contains a label (text or alternative), and the glossary \"Intitulé de lien\", Note 4, fails a link with no content under 6.2. Asks when the content is CSS-generated text, an embedded element, or hidden text beside a name from an attribute. <area> is left to 1.1.2." },
    "link-context-review": { tests: ["6.1.1","6.1.2","6.1.3","6.1.4"], note: "Asks about a link named by a generic phrase or a bare file format whose only context is an aria-describedby text or the text of an enclosing <dd>, <dt>, <blockquote> or <figcaption>. The glossary \"Contexte du lien\" lists only the sentence, the <p>, the <li>, the preceding heading, the associated <th> and the <td>, so the context link-name-quality accepts for WCAG 2.4.4 may not count for 6.1.1 to 6.1.4 step 2. A question, since the link's sentence or a preceding heading may still make it explicit." },
    "link-in-text-block": { tests: ["10.6.1"], note: "Fails inline links in running text (a[href] and role=link) that have no underline, no weight or style difference and no other mark (border, shadow, background, icon, generated content), and whose color contrast with the surrounding text is below 3:1. That is 10.6.1 step 2 (3:1 between link and surrounding text for links shown only by color). A link shown only by a color at 3:1 or more is asked about, since step 2 also needs a non-color cue on hover and focus. It checks only the default state; link-state-colors-review asks about the visited, active, hover and focus colors of step 3." },
    "link-label-in-name-sources": { tests: ["6.1.5"], note: "Fails a link (a[href] or role=\"link\", not an SVG link) with visible text when its title, its aria-label or the text its aria-labelledby points to does not contain that text. That is 6.1.5 steps 1 and 2, which check the content of each of these sources; the glossary \"Intitulé (ou nom accessible) de lien\", note 2, says the same of the title. Punctuation and capital letters are ignored (particular cases of 6.1.5). Asks when the visible label may be a symbol, or when a source differs only by an abbreviation or by text in parentheses." },
    "link-name-present": { tests: [], note: "Fails a[href], area[href] and role=link elements with no accessible name at all. Not mapped to 6.2.1: that test asks for a label in the link content, so a link named only by aria-label, aria-labelledby or title passes here but fails 6.2.1, and an <area> belongs to 1.1.2 (area-alt-present). link-content-label-present checks 6.2.1." },
    "link-name-quality": { tests: ["6.1.1","6.1.2","6.1.3","6.1.4"], note: "Flags a[href], area[href] and role=link elements whose full accessible name, whatever its source (text, img alt, SVG), is a generic phrase or a bare file format with no adjacent context. That is the question 6.1.1 to 6.1.4 step 2 asks per link type: does the name alone or with its context give the link's purpose and destination. Unnamed links are explicitly left out, so 6.2.1 is not covered. It accepts an aria-describedby text or a <dd>, <dt>, <blockquote> or <figcaption> as context, which the glossary \"Contexte du lien\" does not list; link-context-review asks about those links." },
    "link-state-colors-review": { tests: ["10.6.1"], note: "Asks about a link in a run of text, shown only by color at rest, when an author rule for :visited, :active, :hover or :focus changes only its color, when no author rule sets its color (the browser's visited color then differs), or when a style sheet cannot be read. 10.6.1 step 3 requires the 3:1 check « pour les différents états du lien s'ils sont présentés au moyen d'une couleur différente ». A static scan cannot put a link in those states, so it asks; link-in-text-block judges the resting state." },
    "list-children-valid": { tests: ["9.3.1","9.3.2"], note: "Fails a <ul>/<ol> (with no role other than list) with a direct child that is not an <li>/role=listitem (or script/template), so the list is not structured with ul/li (9.3.1) or ol/li (9.3.2), step 2. Not linked to 8.2.1: the rule accepts a child with role=listitem and skips hidden lists, while HTML accepts only li; html-nesting-valid reports list nesting under 8.2.1." },
    "listbox-name-present": { tests: [], note: "Checks that role=listbox has a name from aria-label, aria-labelledby, title or an associated label. It accepts a wrapping <label>, which 11.1.1 does not list. It also fails a <label for> pointing at a role=listbox element that a label cannot name, which meets 11.1.1 condition 3 to the letter. Not mapped to 11.1.1: field-label-listed-source reports 11.1.1 for every form field, from the sources 11.1.1 lists only. Not mapped to 7.1.1: it passes when an accessible alternative exists." },
    "listbox-option-groups-absent": { tests: ["11.8.1"], note: "Fails an element with role=\"listbox\" (not <select>) that contains role=\"group\". The 11.8 technical note says options cannot be grouped with ARIA, and a list that needs grouping built with role=\"listbox\" does not conform to 11.8; a role=\"group\" shows the options were grouped. The note names the criterion, not a test: 11.8.1 is the test on grouping options." },
    "listitem-parent-valid": { tests: ["9.3.1","9.3.2"], note: "Fails an <li> whose parent is not <ul>/<ol>/<menu> or role=list/none/presentation, so items grouped as a list are not structured with a ul/ol container. That is step 2 of 9.3.1 or 9.3.2; the rule cannot tell ordered from unordered, so both apply. Not linked to 8.2.1: HTML does not accept an li in a role=list container, which this rule passes; html-nesting-valid reports it under 8.2.1." },
    "main-element-structure": { tests: ["9.2.1"], note: "Steps 4 and 5 of 9.2.1 on HTML5 pages: fails role=\"main\" with no <main> element (step 4), and a second <main> that has no hidden attribute, even if CSS or aria-hidden hides it (step 5 and the 9.2 technical note). Asks when the page has neither <main> nor role=\"main\", or when a <main> is hidden only by an ancestor. Not applicable when the doctype is not HTML5 (9.2 particular case). Steps 1 to 3 and 6 are not checked." },
    "manual-review": { tests: ["12.8.1","12.9.1","10.7.1"], note: "Always-on page-level prompt to review by keyboard whether focus can leave every component (12.9.1 step 2), whether tab order is coherent (12.8.1 step 2) and whether the focus indicator is visible (10.7.1). It is a reminder only and gives no finding on any element." },
    "markup-validation-review": { tests: ["8.2.1"], note: "Asks on every page for the W3C validator report on the generated source, which is 8.2.1 step 1. The DOM no longer shows unclosed or misnested tags, repeated attributes and the other errors the parser repairs, so the rules that report 8.2.1 from the DOM cover part of the test only; this question keeps 8.2 from rolling up to pass on their word alone." },
    "media-alternative-transcript-evidence": { tests: [], note: "Flags <audio>/<video> with no transcript found nearby or through aria-describedby (WCAG 1.2.1). Not linked to 4.1.1 to 4.1.3: those tests accept only a transcript, or a link or button to one, right before or after the media (glossary \"Lien ou bouton adjacent\"), and this rule stays silent on a transcript referenced by aria-describedby elsewhere in the page. media-transcript-adjacent reports 4.1.1 to 4.1.3." },
    "media-transcript-adjacent": { tests: ["4.1.1","4.1.2","4.1.3"], note: "Passes an <audio>/<video> whose neighbour just before or after it in the code is a link or button naming a transcript, or a block whose text does, which is the presence step (step 2) of 4.1.1 to 4.1.3 as the glossary \"Lien ou bouton adjacent\" defines adjacency. Otherwise it asks: the media may not need a transcript, or a video may meet 4.1.2/4.1.3 through audio description. It cannot tell audio-only, video-only and synchronised media apart, so each finding carries the three tests." },
    "menuitem-name-present": { tests: ["7.1.1"], note: "Checks that menuitem, menuitemcheckbox and menuitemradio elements have a non-empty name. These are parts of a script-driven menu component, and 7.1.1 step 2 requires an explicit name. Not a form field, so 11.1 does not apply. Not mapped to 11.9.1 (where other RGAA tools put this check): 11.9.1 covers buttons in a form, not menu items." },
    "meta-redirect-immediate": { tests: ["13.1.2"], note: "Asks about the first meta refresh when it sends the visitor to another address after a delay: 13.1.2 requires the redirect to be immediate, with no 20-hour exception, but a redirect from an obsolete address to the new page is essential and makes 13.1 not applicable, which only a person can tell. A delay of 0 passes." },
    "meta-refresh-no-exceptions": { tests: [], note: "AAA rule that fails any meta refresh with a positive delay. Not linked to 13.1: a refresh of 20 hours or more without a URL passes 13.1.1 and is no redirect for 13.1.2, yet this rule fails it, and a delayed redirect from an obsolete address is essential, so 13.1 does not apply to it. meta-refresh-no-url-timing reports 13.1.1 and meta-redirect-immediate 13.1.2." },
    "meta-refresh-no-url-timing": { tests: ["13.1.1"], note: "Fails the first meta refresh when it reloads the page itself (no URL, or the page's own address) with a delay under 20 hours, 0 included: a meta refresh cannot be stopped, relaunched or lengthened, so only the last condition of 13.1.1 step 2, a limit of twenty hours at least, can hold. A delay of 72000 seconds or more passes. embedded-refresh-review asks about refreshes from object, embed, svg and canvas." },
    "meta-refresh-timing-absent": { tests: [], note: "Fails the first meta http-equiv=refresh with a delay between 1 second and 20 hours (WCAG 2.2.1). Not linked to 13.1: RGAA splits refreshes (13.1.1, where a limit of exactly 20 hours passes) from redirects (13.1.2, which must be immediate, with no 20-hour exception, unless they leave an obsolete address), and this rule treats both alike. meta-refresh-no-url-timing reports 13.1.1 and meta-redirect-immediate 13.1.2." },
    "meta-viewport-large": { tests: [], note: "Flags viewport meta tags with user-scalable=no or maximum-scale<5. user-scalable=no, or maximum-scale below 2, blocks graphic zoom to 200%, which 10.4.2 step 1 checks. Values from 2 up to 5 are only a best practice and do not fail RGAA, so the auditor must check the actual value. Not mapped to 10.4.2: the rule flags anything below 500% zoom; RGAA requires 200%, which meta-viewport-zoom-enabled checks." },
    "meta-viewport-zoom-enabled": { tests: [], note: "Fails a viewport meta that sets user-scalable=no or maximum-scale below 2, which blocks pinch zoom to 200% (WCAG 1.4.4). Not linked to 10.4.2: that test passes when any one of the browser text zoom, the browser graphic zoom or a zoom control of the site reaches 200%, and a viewport meta tag does not stop all of them in every audit environment. viewport-zoom-review asks the 10.4.2 question on the same tags." },
    "meter-name-present": { tests: [], note: "Fails an element with explicit role=\"meter\" that has no name from aria-label, aria-labelledby or title. It also fails a <label for> pointing at it, which meets 11.1.1 condition 3. Not mapped to 11.1.1: field-label-listed-source reports 11.1.1 for every form field, from the sources 11.1.1 lists only. Not mapped to 7.1.1: it passes when an accessible alternative exists, and a meter is not necessarily script-driven." },
    "mouse-only-event-handlers": { tests: ["7.3.1"], note: "Flags elements with inline pointer-only handlers (onmouseover, onmousedown, ondblclick, and so on) and no keyboard or focus handler that can run, and asks whether they work by keyboard. A focus handler counts only on an element that can take focus, and a key handler only when the element or a descendant can. That is 7.3.1 steps 2-3 (an element with a JS event handler must be keyboard-accessible, or have an equivalent). It only sees inline attributes." },
    "nested-interactive-controls-absent": { tests: [], note: "Flags interactive controls that contain another operable control (for example a button inside a[href]). Not linked to 8.2.1: the rule fails nesting that uses only ARIA roles, which the W3C validator only warns about (since Nu 26.8.6), and it misses disabled or tabindex descendants the validator rejects; html-nesting-valid reports the HTML nesting errors under 8.2.1. Not mapped to 7.1.1 (where other RGAA tools put this check): native nested controls are not scripted components." },
    "no-autoplay-audio": { tests: ["4.10.1"], note: "Flags unmuted autoplaying <audio>/<video> with no native controls, and every <bgsound> and every <embed> or <object> that loads sound, video or a plugin, and asks about the 3-second rule and a stop or volume mechanism. That is 4.10.1 step 1, which lists those five elements. Sound started by a script is not detected." },
    "object-image-role-img": { tests: ["1.1.6"], note: "Checks each <object type=\"image/...\"> not marked decorative. Passes role=\"img\" with aria-labelledby, aria-label or title. Fails an object with no text alternative, no fallback content and no link or button right after it, which meets none of the conditions of 1.1.6 short of a replacement mechanism the page would have to offer. Asks when there is a text alternative without role=\"img\" (the test wording requires both, the methodology validates on the alternative alone), when a link or button follows (does it lead to an alternative content?), and when there is only fallback content." },
    "object-text-alternative-present": { tests: [], note: "Fails an <object> with no fallback text, no ARIA name and no title. Not mapped to 1.1.6: that test covers only type=\"image/...\", while the rule fails every <object>, and RGAA passes an object followed by a link or button to an alternative content, which this rule fails. object-image-role-img checks 1.1.6 as RGAA words it." },
    "object-text-alternative-quality": { tests: ["1.3.4"], note: "Asks a human to judge the relevance of an <object>'s title, ARIA name or fallback content, which is 1.3.4 step 2 (fallback content is explicitly listed there). Scope mismatch: 1.3.4 only covers image objects." },
    "office-document-link": { tests: ["13.3.1"], note: "Lists each link, form or submit button that downloads an office document for a person to check one of the conditions of 13.3.1: the document is accessible, or an accessible version is offered. The document is found by the download filename, the address path, a query-string value or the form action, with the Office, OpenDocument, PDF, EPUB and RTF extensions. Downloads started by script or without such an extension are not found." },
    "optgroup-label-not-empty": { tests: ["11.8.3"], note: "Fails an <optgroup> inside a <select> whose label attribute is empty or only spaces: 11.8.3 step 2 asks whether the label's content is relevant, and an empty one cannot be. Whether a non-empty label is relevant is not judged, so a pass covers only that case." },
    "optgroup-label-present": { tests: ["11.8.2"], note: "Fails an <optgroup> inside a <select> with no label attribute, which is 11.8.2 step 2. An empty label passes, since RGAA only asks for the attribute; optgroup-label-not-empty reports it under 11.8.3." },
    "option-name-present": { tests: ["11.1.1"], note: "Checks that role=option has a non-empty name. The RGAA glossary lists option as a form-field role, so an unnamed option fails 11.1.1 (other RGAA tools use 11.1 too). Not mapped to 7.1.1 (where other RGAA tools put this check): it passes when an accessible alternative exists, and the problem is already reported under 11.1.1." },
    "orientation-content-parity": { tests: ["13.9.1"], note: "Asks about each element that a style rule inside an orientation media condition hides (display: none, visibility: hidden). 13.9.1's second condition asks that the content stays the same in both orientations, even if it is presented differently; whether the hidden content is offered another way, or the orientation is essential, is for a person. css-orientation-lock asks only when the hidden element holds the main content." },
    "p-as-heading": { tests: ["9.1.3"], note: "Flags short <p> text, and short <div> text with only inline markup inside, that is entirely bold (however the bold is applied) and at least 18px, asking whether it is a visual heading without <hx>/role=heading markup. That is the 9.1.3 question: is each passage that acts as a heading structured with <hx> or role=heading plus aria-level?" },
    "page-has-heading-one": { tests: [], note: "Flags pages with no h1 or role=heading aria-level=1. RGAA does not explicitly require an h1, but a missing top level is evidence the auditor weighs in 9.1.1 step 2 (whether the heading hierarchy is relevant). Not mapped to 9.1.1: RGAA does not require an h1." },
    "page-language-present": { tests: ["8.3.1"], note: "Checks the two conditions of 8.3.1: a language on <html> (lang, or xml:lang on XHTML 1.1 or a page parsed as XML), or on every text of <body> or one of its parents. Fails when some rendered text has no language at all. Asks when the language is given by xml:lang alone on a version where the glossary \"Langue par défaut\" asks for lang, since the test's wording accepts either attribute." },
    "page-title-patterns": { tests: ["8.6.1"], note: "Manual signal on the <title> content (generic words like 'Home' or 'Untitled', very short titles, and titles duplicated or templated across crawled pages). This is exactly 8.6.1 step 2: is the title relevant enough to find the page in history or tabs." },
    "page-title-present": { tests: ["8.5.1"], note: "Fails when the <title> element is missing or its text is empty, which is 8.5.1 step 1 (a <title> exists). An empty title is treated as an absent title rather than as a relevance (8.6.1) problem." },
    "password-paste-enabled": { tests: [], note: "Concerns WCAG 3.3.8 Accessible Authentication (WCAG 2.2), which RGAA 4.1.2 does not include. No RGAA test covers paste blocking on authentication fields." },
    "presentation-role-conflict": { tests: [], note: "Asks about role=\"presentation\"/\"none\", or <img alt=\"\">, combined with a global ARIA attribute such as aria-label, or with focusability. Not mapped to 1.2.1: most of its findings are on elements other than <img>, or on attributes 1.2.1 does not name (aria-describedby, focusability), and it does not look at title. img-decorative-no-alternative checks 1.2.1 step 2 on decorative images." },
    "presentational-attributes-absent": { tests: ["10.1.2"], note: "Fails on each HTML element carrying an attribute 10.1.2 step 1 lists, with its exceptions: size allowed on <select>, width and height on <img>, <object>, <embed>, <canvas> and <svg>. SVG and MathML content is not checked, where those attributes are geometry rather than presentation. Hidden content is checked too, since 10.1.2 judges the generated source." },
    "presentational-children-focusable-absent": { tests: [], note: "Flags tab stops inside roles with presentational children (button, tab, option...). For native button the Nu checker reports interactive content or a tabindex descendant as a nesting error (8.2.1 step 2). Explicit-role cases are mostly not validator errors, and the effect on AT output (7.1.2) is not directly what the rule tests. Not mapped to 8.2.1: the validator 8.2.1 relies on reports only the native-button case." },
    "presentational-elements-absent": { tests: ["10.1.1"], note: "Fails on each element 10.1.1 step 1 lists (basefont, big, blink, center, font, marquee, s, strike, tt), and on <u> when the doctype is not HTML5 (step 2). Written for RGAA, so it checks exactly that list. Hidden content is checked too, since 10.1.1 judges the generated source." },
    "progressbar-name-present": { tests: [], note: "Fails an element with explicit role=\"progressbar\" that has no author-supplied name and, on a labelable <progress> or <meter>, no associated label. It accepts a wrapping <label>, which 11.1.1 does not list. Not mapped to 11.1.1: field-label-listed-source reports 11.1.1 for every form field, from the sources 11.1.1 lists only. Not mapped to 7.1.1: it passes when an accessible alternative exists, and a progressbar is not necessarily script-driven." },
    "radio-group-present": { tests: ["11.5.1"], note: "Asks about two or more radio buttons with the same name, in the same form, that are not all inside one <fieldset>, role=\"group\" or role=\"radiogroup\" (an outer one holding the whole set counts), the three ways 11.5.1 accepts. 11.5.1 applies \"si nécessaire\", so a person decides. Custom role=\"radio\" widgets are not checked." },
    "region": { tests: [], note: "Flags content under <body> that is outside any landmark. RGAA does not require all content to be inside landmarks: 12.6.1 accepts alternatives to landmarks for specific zones only, and 9.2.1 covers header/nav/main/footer structure, not leftover content." },
    "role-img-aria-name": { tests: ["1.1.1"], note: "Fails an exposed element with role=\"img\" (not <img>, not an outer <svg>) whose text alternative does not come from aria-labelledby or aria-label, the two sources 1.1.1 step 4 lists for role=\"img\": a title-only name fails, as does no name at all. An element in the SVG namespace named only by a <title> child is asked about, since RGAA contradicts itself on <title> (1.1.5 step 5 against 1.3.6). An element with aria-hidden=\"true\" is left out, as the glossary allows only that for a decorative role=\"img\"." },
    "role-img-text-alternative-present": { tests: [], note: "Fails an exposed element other than <img> and <svg> with role=\"img\", \"graphics-symbol\" or \"graphics-document\" that has no name. Not mapped to 1.1.1: the rule accepts a title attribute or an SVG <title> as the name, which 1.1.1 step 4 does not list for role=\"img\", and its graphics-* findings belong to no RGAA test. role-img-aria-name checks 1.1.1 for role=\"img\"." },
    "scope-attr-valid": { tests: ["5.7.2"], note: "Flags scope values other than row/col/rowgroup/colgroup. On a th with an invalid scope, 5.7.2 fails because it requires scope=\"row\" or scope=\"col\". The rule accepts rowgroup/colgroup, so it covers only part of 5.7.2. Not linked to 8.2.1: the rule trims values and skips empty ones, which the validator rejects; html-elements-attributes-valid reports scope values under 8.2.1." },
    "scripted-components-review": { tests: ["7.1.1","7.1.2","7.1.3"], note: "Asks on every page with script (an executable <script>, an inline event handler, a javascript: URL or a custom element) for a person to check each scripted component against 7.1.1 to 7.1.3. It always asks, because the engine cannot see behaviour attached from script files. It lists candidate elements from the markup (widget roles, tabindex, inline handlers, contenteditable, aria-expanded and similar states) as a starting point, not a complete list. A page with no script is notApplicable, since 7.1 applies to scripts." },
    "scrollable-region-focusable": { tests: [], note: "Flags containers with overflow auto/scroll that have no focusable descendant and are not focusable themselves (keyboard scrolling). No RGAA test covers keyboard scrolling of a plain CSS scroll region: 7.3 needs a script handler, 10.14/12.11 cover extra content shown on hover, focus or activation, and 12.9 covers keyboard traps." },
    "searchbox-name-present": { tests: [], note: "Checks that role=searchbox has a name from aria-label, aria-labelledby, title or an associated label. It accepts a wrapping <label> and a placeholder on a text-like <input>, which 11.1.1 does not list, so a placeholder-only field passes here while it fails 11.1.1. Not mapped to 11.1.1: field-label-listed-source reports 11.1.1 for every form field, from the sources 11.1.1 lists only. Not mapped to 7.1.1: it passes when an accessible alternative exists." },
    "server-side-image-map-absent": { tests: ["1.1.4"], note: "Asks about each <img ismap> inside a link, which is step 1 of 1.1.4 (find <img> with ismap). 1.1.4 passes if the page also has links giving the same destinations (step 2), which this rule cannot check, so it asks rather than fails. An <img ismap> outside a link does nothing, and the rule leaves it to the validator. 1.1 is outside the WCAG-derived candidates, but the element and attribute match exactly.", outsideCorrespondence: {"1.1.4":"RGAA files 1.1.4 under WCAG 1.1.1 and the engine files server-side image maps under 2.1.1 (Keyboard), but the rule and the test look for the same thing: 1.1.4 step 1 finds each <img> with ismap."} },
    "skip-link": { tests: ["12.7.1","12.7.2"], note: "Flags skip links whose #fragment does not resolve to a usable target. A skip link is recognised by its wording in the shipped locales ('skip', 'aller au contenu', 'accès direct', 'zum Inhalt springen', 'saltar al contenido', '本文へ') or as the first link of the page placed before main. A dead skip link means the main zone cannot be skipped, which bears on 12.7.1 (where other RGAA tools report a broken skip link), and it fails 12.7.2's condition that the link works ('Le lien est fonctionnel'). The rule does not check the link's visibility or consistency across pages, and a skip link can target zones other than main." },
    "skip-link-present": { tests: ["12.7.1"], note: "Fails a page whose navigation block comes before the visible <main> when no same-page link leads to the main content zone (to <main>, or to an element just before or at the start of it), and a skip link whose target does not exist. That is 12.7.1 step 2: the zone can be skipped or reached by a link. Asks when no navigation comes before the zone (the one-page particular case), and on a skip link whose target is hidden or not at the start of the zone. Whether the link is visible on focus is left to 12.7.2." },
    "slider-name-present": { tests: [], note: "Checks that explicit role=slider has a name from aria-label, aria-labelledby, title or an associated label. Native input[type=range] without the role is out of the rule's scope. It accepts a wrapping <label> and a placeholder on a text-like <input>, which 11.1.1 does not list, so a placeholder-only field passes here while it fails 11.1.1. Not mapped to 11.1.1: field-label-listed-source reports 11.1.1 for every form field, from the sources 11.1.1 lists only. Not mapped to 7.1.1: it passes when an accessible alternative exists." },
    "spinbutton-name-present": { tests: [], note: "Checks that role=spinbutton has a name from aria-label, aria-labelledby, title or an associated label. It accepts a wrapping <label> and a placeholder on a text-like <input>, which 11.1.1 does not list, so a placeholder-only field passes here while it fails 11.1.1. Not mapped to 11.1.1: field-label-listed-source reports 11.1.1 for every form field, from the sources 11.1.1 lists only. Not mapped to 7.1.1: it passes when an accessible alternative exists." },
    "summary-name-present": { tests: [], note: "Flags <summary> elements with an empty name. A native details/summary disclosure is not script-generated, so 7.1.1 does not strictly apply. 11.9.1 covers only buttons inside a form, and no other candidate test concerns disclosure widgets. The auditor may still choose to treat a scripted summary under 7.1.1." },
    "svg-hidden-no-alternative": { tests: ["1.1.5","1.2.4"], note: "Fails an <svg aria-hidden=\"true\"> that carries a text alternative: aria-label, aria-labelledby, a title attribute, or a non-empty <title> or <desc>, in its own content or in a <symbol>/<svg> it draws through a same-document <use> (as the note of criterion 1.2 asks). As a decorative image it breaks conditions 2 to 4 of 1.2.4. If the alternative means the image carries information, it is hidden from assistive technology and has no role=\"img\", failing 1.1.5. Which of the two applies needs a human." },
    "svg-image-text-alternative-present": { tests: [], note: "Targets SVG <image> child elements. RGAA 1.1.5 covers the <svg> root, and 1.1.1 covers <img> and role=\"img\", so no RGAA test is about naming an inner SVG <image>. It would only matter if that element were given role=\"img\", and role-img-text-alternative-present already covers that case." },
    "svg-role-img": { tests: ["1.1.5"], note: "Fails an exposed outer <svg> named by aria-labelledby, aria-label or a <title> child but without role=\"img\": 1.1.5 step 4 says the test is failed without the role. An <svg role=\"img\"> named only by <title> is asked about, since 1.1.5 step 5 lists only the ARIA sources while 1.3.6 treats <title> as the SVG's alternative. An unnamed <svg role=\"img\"> is left to svg-text-alternative-present." },
    "svg-text-alternative-present": { tests: ["1.1.5"], note: "Fails an <svg> root that seems meant to convey information but has no <title> text and no aria-label/aria-labelledby, which is 1.1.5 step 5. It does not enforce the role=\"img\" requirement of step 3, which svg-role-img checks." },
    "svg-text-alternative-quality": { tests: ["1.3.6"], note: "Asks a human to judge the relevance of an <svg>'s existing title/ARIA name, which is 1.3.6 step 2. It also includes desc-only cases." },
    "tab-name-present": { tests: ["7.1.1"], note: "Checks that role=tab has a non-empty name. A tab is part of a script-driven tab panel component, and 7.1.1 step 2 requires an explicit name. Not a form field." },
    "tabindex": { tests: ["12.8.1"], note: "Flags positive tabindex values, which override the natural focus order. This is direct evidence for 12.8.1 step 2, whether the tab order stays coherent, though a positive tabindex is not a failure by itself." },
    "table-duplicate-name": { tests: [], note: "Asks (cantTell) about tables whose summary attribute repeats the caption. Not mapped to 5.2.1: in HTML5 the summary attribute is not a summary (5.1.1 step 2, glossary \"Résumé (de tableau)\"), and 5.2 concerns only complex data tables, while this rule asks about any table. complex-table-summary-quality asks 5.2.1's question on complex tables." },
    "table-fake-caption": { tests: ["5.4.1"], note: "Flags tables with no <caption> whose first row is a single cell above multi-cell rows, asking whether that cell is a visual title not tied to the table. That is 5.4.1 step 2: is the data table's title given by caption, title, aria-label or aria-labelledby? A table already named by title, aria-label or aria-labelledby is not asked about, nor one whose role is not table, grid or treegrid (a layout table is 5.8's matter)." },
    "table-headers-attr-valid": { tests: ["5.7.4"], note: "Fails a td/th whose headers attribute references an id that is missing, points to a non-cell, points to the cell itself, or sits in another table, so headers does not list the ids of the associated headers (5.7.4 step 2, second condition). Not linked to 8.2.1: the rule accepts headers that name a td, which the validator rejects (it wants a th of the same table); html-elements-attributes-valid reports headers under 8.2.1." },
    "table-th-has-data-cells": { tests: [], note: "Fails a table (not role=presentation) that has <th> but no <td> at all. If the auditor judges it a layout table, the <th> use fails 5.8.1 step 2. If it is a data table whose cells are all marked <th>, no RGAA test forbids that (5.6.4 allows th), so the auditor must decide which applies. Not mapped to 5.8.1: only a failure if the auditor judges the table a layout table. Not mapped to 5.7.1 (where other RGAA tools put this check): a table with no <td> says nothing about the id, scope or role that 5.7.1 checks." },
    "target-size-minimum": { tests: [], note: "Checks the 24x24 CSS px target size and spacing exception of WCAG 2.5.8, a WCAG 2.2 criterion RGAA 4.1.2 does not include. No RGAA test measures pointer target size." },
    "td-has-header": { tests: [], note: "In large tables (4x4 or more, no colspan/rowspan, and no role other than table, grid or treegrid), fails a non-empty <td> with no headers attribute and no header cell (<th>, or role columnheader or rowheader) above it in its column or before it in its row. Not mapped to 5.7.4: that test covers cells \"associée à un ou plusieurs en-têtes possédant un attribut id\", and a cell with no header at all is not one. Not mapped to 5.6.1/5.6.2: a cell without associated headers does not show that the headers were not declared with <th>." },
    "textbox-name-present": { tests: [], note: "Checks that role=textbox has a name from aria-label, aria-labelledby, title or an associated label. It accepts a wrapping <label> and a placeholder on a text-like <input>, which 11.1.1 does not list, so a placeholder-only field passes here while it fails 11.1.1. Not mapped to 11.1.1: field-label-listed-source reports 11.1.1 for every form field, from the sources 11.1.1 lists only. Not mapped to 7.1.1: it passes when an accessible alternative exists." },
    "th-scope-row-col": { tests: ["5.7.2","5.7.3"], note: "Asks about a <th> with scope=\"rowgroup\" or \"colgroup\" (not in a presentation table). 5.7.2 wants scope=\"row\" or \"col\" on a header over a whole row or column, and 5.7.3 wants no scope and a unique id on one over part of it (glossary \"En-tête de colonne ou de ligne\"), so the header fails one of the two tests. Which one depends on how much of the table it covers, so the rule asks." },
    "title-placeholder-identical": { tests: ["11.2.2"], note: "Asks about an <input> or <textarea> whose non-empty title and placeholder differ. The glossary \"Étiquette de champ de formulaire\" says the placeholder may be read in place of the title, so « lorsque ces deux attributs title et placeholder sont présents, ils doivent être identiques ». No test names this requirement; 11.2.2, which judges whether a title gives the field's exact function, is the closest, so the rule asks rather than fails." },
    "tooltip-name-present": { tests: [], note: "Flags role=tooltip with an empty name, which in practice means an empty tooltip. A tooltip is supplementary content, not an operable component whose name 7.1.1 step 2 evaluates. None of the candidate tests checks tooltip content, so a fit to 7.1.1 would be weak." },
    "treeitem-name-present": { tests: ["7.1.1"], note: "Checks that role=treeitem has a non-empty name. A tree item is part of a script-driven tree component, and 7.1.1 step 2 requires an explicit name." },
    "valid-lang": { tests: ["8.8.1"], note: "Checks that lang on elements other than <html> has a registered primary language subtag (the glossary \"Code de langue\" reads only the part before the hyphen). That is the 'valide' condition of 8.8.1 for language changes; relevance is not checked." },
    "video-caption": { tests: ["4.3.1"], note: "Flags <video> without a <track kind=\"captions\"> (with a src), raising the question of 4.3.1 step 2 (are synchronised captions present?). A video with only kind=\"subtitles\" tracks is asked about too, since the glossary \"Sous-titres synchronisés\" (note 2) does not count translation subtitles as captions." },
    "video-captions-track-kind": { tests: ["4.3.2"], note: "Fails a <video> whose subtitle tracks (with a src) are all kind=\"subtitles\" (or have no kind, which means subtitles), with none kind=\"captions\", when one is in the video's language. That is 4.3.2 as written. When none is in the video's language (or srclang is missing), it asks instead: a translation track is not a caption track (glossary \"Sous-titres synchronisés\", note 2), and then 4.3.2 does not apply. Whether the video is pre-recorded synchronised media, and whether a track carries captions at all, needs a human." },
    "video-poster-text-alternative-present": { tests: [], note: "Checks that a <video poster> has an accessible name. No RGAA 4.1.2 test targets poster images: the theme-1 tests list img/area/input/svg/object/embed/canvas, and the theme-4 tests are about transcripts, captions and AT compatibility of the media player, not naming a <video>." },
    "viewport-zoom-review": { tests: ["10.4.2"], note: "Asks about each viewport meta tag that disables zoom or caps it below 2, the tags meta-viewport-zoom-enabled fails. 10.4.2 is met when text reaches 200% by any one of its three conditions (browser text zoom, browser graphic zoom, a zoom control of the site), and the tag acts only on pinch zoom, so whether it blocks all three depends on the audit environment. It never fails." },
    "widget-label-in-name": { tests: ["7.1.3"], note: "Fails an element with an ARIA widget role other than link, button or form field (tab, menuitem, menuitemcheckbox, menuitemradio, treeitem, gridcell, option) whose accessible name, from aria-labelledby or aria-label, does not contain its visible text. That is 7.1.3 step 2: the component's name contains at least the visible label. An explicit widget role marks a component built with a script. Punctuation and capital letters are ignored (particular cases of 7.1.3). A title is not checked, since 7.1.3 judges only the accessible name." },
  }
};

module.exports = { RGAA_RULE_TESTS };
